// Custom GLSL Shader for Matrix Digital Rain
const MatrixMaterial = shaderMaterial(
  { uTime: 0, uColor: new THREE.Color('#00ff44'), uScale: new THREE.Vector2(10, 10), uTexture: null },
  // vertex shader
  `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  // fragment shader
  `
    uniform float uTime;
    uniform vec3 uColor;
    uniform vec2 uScale;
    uniform sampler2D uTexture;
    varying vec2 vUv;

    float random(vec2 st) {
        return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
    }

    void main() {
        vec2 st = vUv * uScale; 
        
        vec2 id = floor(st);
        vec2 localUv = fract(st);
        
        float offset = random(vec2(id.x, 0.0));
        float speed = 0.5 + offset * 1.5;
        
        // Falling down
        float y = fract(-st.y + uTime * speed + offset * 10.0);
        
        // Bright head, fading tail
        float head = smoothstep(0.95, 1.0, y);
        float tail = smoothstep(0.0, 1.0, y) * (1.0 - head);
        float intensity = head + tail * 0.7;
        
        // Randomly drop some columns completely
        if (random(vec2(id.x, 1.0)) > 0.7) {
            intensity = 0.0;
        }
        
        // Pick a random character from the 16x16 texture atlas
        // Change character a few times per second
        float charIndex = floor(random(id + floor(uTime * 5.0)) * 256.0);
        vec2 atlasUv = vec2(
            mod(charIndex, 16.0) / 16.0,
            floor(charIndex / 16.0) / 16.0
        );
        vec2 finalUv = atlasUv + (localUv / 16.0);
        
        vec4 texColor = texture2D(uTexture, finalUv);
        float char = texColor.r; // Since texture is black and white
        
        intensity *= char;
        
        // White head, green tail
        vec3 finalColor = mix(uColor, vec3(1.0, 1.0, 1.0), head);
        
        gl_FragColor = vec4(finalColor * intensity, intensity * 0.9);
    }
  `
);
extend({ MatrixMaterial });

// Generate Katakana Texture Atlas globally (Singleton) so we don't create 20 textures
const globalMatrixTexture = (() => {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, 512, 512);
  ctx.fillStyle = '#ffffff';
  ctx.font = '28px monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  
  // Draw a 16x16 grid of random katakana
  for (let i = 0; i < 16; i++) {
    for (let j = 0; j < 16; j++) {
      // Katakana unicode range is 0x30A0 to 0x30FF
      const char = String.fromCharCode(0x30A0 + Math.random() * 96);
      ctx.fillText(char, i * 32 + 16, j * 32 + 16);
    }
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  // ensure crisp pixel lookup
  texture.minFilter = THREE.NearestFilter;
  texture.magFilter = THREE.NearestFilter;
  return texture;
})();

// Animated Material Wrapper
const AnimatedMatrixMaterial = ({ scale = [20, 10], color = "#00ff44", opacity = 1 }) => {
  const materialRef = useRef();

  const vecScale = useMemo(() => new THREE.Vector2(scale[0], scale[1]), [scale[0], scale[1]]);
  const col = useMemo(() => new THREE.Color(color), [color]);

  useFrame((state) => {
    if (materialRef.current) {
      materialRef.current.uTime = state.clock.elapsedTime;
    }
  });
  return (
    <matrixMaterial 
      ref={materialRef} 
      transparent 
      uScale={vecScale}
      uColor={col}
      uTexture={globalMatrixTexture}
      side={THREE.DoubleSide}
      depthWrite={false}
      blending={THREE.AdditiveBlending}
    />
  );
};

// 3D Point Cloud Brain Centerpiece
const PointCloudBrain = ({ position }) => {
  const brainRef = useRef();

  // Generate a procedural point cloud shaped like a brain
  const brainGeometry = useMemo(() => {
    const points = [];
    // Generate 15,000 points
    for (let i = 0; i < 15000; i++) {
      // Random point in sphere
      const u = Math.random();
      const v = Math.random();
      const theta = 2 * Math.PI * u;
      const phi = Math.acos(2 * v - 1);
      const r = Math.cbrt(Math.random()) * 80; // Radius 80

      let x = r * Math.sin(phi) * Math.cos(theta);
      let y = r * Math.sin(phi) * Math.sin(theta);
      let z = r * Math.cos(phi);

      // Shape into brain (ellipsoid)
      x *= 0.75; // narrower width
      y *= 0.85; // slightly squashed height
      z *= 1.15; // elongated length

      // Longitudinal fissure (dip in the middle of X)
      const fissureDip = Math.max(0, 1 - Math.abs(x) / 10);
      y -= fissureDip * 15;

      // Reject some points to simulate folds (sulci)
      const foldNoise = Math.sin(x * 0.2) * Math.cos(y * 0.2) * Math.sin(z * 0.2);
      if (foldNoise > 0.15) continue; // carve out empty space

      points.push(x, y, z);
    }
    const floatArray = new Float32Array(points);
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(floatArray, 3));
    return geometry;
  }, []);

  useFrame((state, delta) => {
    if (brainRef.current) {
      // Rotate the entire brain in 3D
      brainRef.current.rotation.y += delta * 0.5;
      brainRef.current.rotation.x = Math.sin(state.clock.elapsedTime * 0.5) * 0.1;
      // Hover effect
      brainRef.current.position.y = position[1] + Math.sin(state.clock.elapsedTime * 2) * 10;
    }
  });

  return (
    <group position={position} ref={brainRef}>
      {/* Audio Visualization Rings */}
      <mesh rotation={[Math.PI / 2, 0, 0]}>
        <ringGeometry args={[120, 125, 64]} />
        <meshBasicMaterial color="#00ff44" transparent opacity={0.3} side={THREE.DoubleSide} />
      </mesh>
      <mesh rotation={[Math.PI / 2, 0, 0]} scale={[1.2, 1.2, 1.2]}>
        <ringGeometry args={[120, 122, 64]} />
        <meshBasicMaterial color="#0088ff" transparent opacity={0.2} side={THREE.DoubleSide} />
      </mesh>
      
      <points geometry={brainGeometry}>
        <pointsMaterial 
          size={1.5} 
          color="#00ff44" 
          transparent 
          opacity={0.8}
          blending={THREE.AdditiveBlending}
          depthWrite={false}
        />
      </points>
      {/* Inner glowing core so it's not entirely hollow */}
      <mesh>
        <sphereGeometry args={[40, 16, 16]} />
        <meshBasicMaterial color="#00ff44" transparent opacity={0.1} blending={THREE.AdditiveBlending} />
      </mesh>
      <pointLight intensity={3} color="#00ff88" distance={600} />
    </group>
  );
};

