const WorldAutopilot = ({ position, rotation, visible }) => {
  const scroll = useScroll();
  const [hasLocked, setHasLocked] = useState(false);
  const [voiceStatus, setVoiceStatus] = useState('Idle');
  const [voiceText, setVoiceText] = useState('');
  const uiGroupRef = useRef();

  // Voice AI Auto-activation
  useEffect(() => {
    if (visible && !hasInitializedVoice && voiceStatus === 'Idle') {
      hasInitializedVoice = true;
      setVoiceStatus('Initializing Voicebox...');
      fetch('http://localhost:3001/api/voice', { method: 'POST' })
        .then(res => res.json())
        .then(data => {
          setVoiceStatus(data.status);
          setVoiceText(data.text);
          // Auto clear after 5 seconds
          setTimeout(() => {
            setVoiceStatus('Idle');
            setVoiceText('');
          }, 5000);
        })
        .catch(e => {
          console.error(e);
          setVoiceStatus('Voice Offline');
        });
    }
  }, [visible, voiceStatus]);

  useFrame((state) => {
    if (!visible) return;
    
    // UI Floats above the brain
    if (uiGroupRef.current) {
      uiGroupRef.current.position.y = 450 + Math.sin(state.clock.elapsedTime) * 10;
    }
    
    // Trigger scroll lock for Autopilot
    if (scroll.offset > 0.675 && scroll.offset < 0.69 && !hasLocked && !window.autopilotLocked) {
      window.autopilotLocked = true;
      setHasLocked(true);
      
      setTimeout(() => {
        window.autopilotLocked = false;
      }, 1500);
    }
    
    if ((scroll.offset < 0.65 || scroll.offset > 0.70) && hasLocked) {
      setHasLocked(false);
      window.autopilotLocked = false;
    }
  });

  return (
    <group visible={visible} position={position} rotation={rotation}>
      
      <MatrixConferenceRoom />

      {/* Voice Transcript overlay */}
      {voiceText && (
        <Html transform position={[0, 300, 0]} scale={3}>
          <div className="bg-black/90 border border-[#00ff44] rounded-full px-8 py-4 text-[#00ff44] text-2xl uppercase tracking-widest whitespace-nowrap">
            <span className="animate-pulse mr-4 text-white">🎙️</span> {voiceText}
          </div>
        </Html>
      )}

      {/* Title Hologram & Logo positioned floating directly above the brain */}
      <group ref={uiGroupRef} position={[0, 450, -200]}>
        <WorldUI 
          position={[0, 0, 0]}
          title="AUTOPILOT"
          description="Autonomous Business Agent"
          logoUrl="/autopilot_logo.png"
          outlineColor="#00ff44"
          titleColor="#ffffff"
          descColor="#00ff44"
          scale={2.5}
        />
      </group>
    </group>
  );
};

export default WorldAutopilot;
