import React, { useState, useEffect } from 'react';
import { Text, Billboard } from '@react-three/drei';
import * as THREE from 'three';

const WorldUI = ({ 
  position, 
  title, 
  description, 
  logoUrl, 
  titleColor = "#ffffff", 
  descColor = "#aaaaaa", 
  outlineColor = "#001133",
  scale = 1,
  visible = true
}) => {
  const [logoTex, setLogoTex] = useState(null);

  useEffect(() => {
    if (logoUrl) {
      const loader = new THREE.TextureLoader();
      loader.load(logoUrl, (tex) => {
        tex.colorSpace = THREE.SRGBColorSpace;
        setLogoTex(tex);
      });
    }
  }, [logoUrl]);

  return (
    <group position={position} visible={visible}>
      <Billboard
        follow={true}
        lockX={false}
        lockY={false}
        lockZ={false}
      >
        <group scale={scale}>
          {logoTex && (
            <mesh position={[0, 80, 0]}>
              <planeGeometry args={[150, 150]} />
              <meshBasicMaterial 
                map={logoTex} 
                transparent 
                depthWrite={false} 
                blending={THREE.AdditiveBlending} 
              />
            </mesh>
          )}
          
          <Text 
            font="/fonts/Roboto.woff" 
            fallbackFonts={[]}
            position={[0, -20, 0]}
            fontSize={50}
            color={titleColor}
            outlineWidth={0.02}
            outlineColor={outlineColor}
            anchorX="center"
            anchorY="middle"
          >
            {title}
          </Text>
          
          {description && (
            <Text 
              font="/fonts/Roboto.woff" 
              fallbackFonts={[]}
              position={[0, -70, 0]}
              fontSize={20}
              color={descColor}
              outlineWidth={0.01}
              outlineColor={outlineColor}
              anchorX="center"
              anchorY="top"
              maxWidth={600}
              textAlign="center"
              lineHeight={1.5}
            >
              {description}
            </Text>
          )}
        </group>
      </Billboard>
    </group>
  );
};

export default WorldUI;
