// --- CITY OF CHARTS (INSTANCED CANDLESTICKS) ---
const candlestickVertexShader = `
  varying vec3 vColor;
  varying vec3 vWorldPos;
  attribute vec3 instColor;

  void main() {
    vColor = instColor;
    vec4 worldPos = modelMatrix * instanceMatrix * vec4(position, 1.0);
    vWorldPos = worldPos.xyz;
    gl_Position = projectionMatrix * viewMatrix * worldPos;
  }
`;

const candlestickFragmentShader = `
  varying vec3 vColor;
  varying vec3 vWorldPos;
  uniform float uTime;
  
  void main() {
    // Add a pulsing scanline effect
    float scanline = sin(vWorldPos.y * 0.02 - uTime * 2.0) * 0.5 + 0.5;
    vec3 glow = vColor * (0.8 + scanline * 0.4);
    
    // Grid pattern on the candlestick
    float grid = step(0.95, fract(vWorldPos.y * 0.1));
    glow += vec3(1.0) * grid * 0.2;
    
    gl_FragColor = vec4(glow, 0.9);
  }
`;

const CityOfCharts = ({ visible }) => {
  const bodyRef = useRef();
  const wickRef = useRef();
  
  const gridSizeX = 40;
  const gridSizeZ = 120; // Increase Z to stretch backwards
  const spacing = 150;
  const count = gridSizeX * gridSizeZ;

  React.useEffect(() => {
    if (!bodyRef.current || !wickRef.current) return;
    
    const dummy = new THREE.Object3D();
    const tempColor = new THREE.Color();
    let i = 0;
    
    for (let x = 0; x < gridSizeX; x++) {
      for (let z = 0; z < gridSizeZ; z++) {
        const posX = (x - gridSizeX/2) * spacing + (Math.random() * 20 - 10);
        // Shift Z heavily into the negative to push it "back" in the world
        const posZ = -((z) * spacing) + 1000 + (Math.random() * 20 - 10);
        
        // Use perlin-like math for trend
        const trend = Math.sin(x * 0.2) + Math.cos(z * 0.2);
        // Force more green candles towards the back (higher z index)
        const isBullish = z > 40 ? (Math.random() > 0.2) : (trend + (Math.random() - 0.5) > 0);
        
        const open = Math.abs(trend) * 400 + Math.random() * 200;
        const close = open + (isBullish ? 1 : -1) * (50 + Math.random() * 300);
        
        const high = Math.max(open, close) + Math.random() * 150;
        const low = Math.max(10, Math.min(open, close) - Math.random() * 150);
        
        const bodyHeight = Math.abs(close - open);
        const bodyY = Math.min(open, close) + bodyHeight / 2;
        
        const wickHeight = high - low;
        const wickY = low + wickHeight / 2;

        // Body
        dummy.position.set(posX, bodyY, posZ);
        dummy.scale.set(40, bodyHeight, 40);
        dummy.updateMatrix();
        bodyRef.current.setMatrixAt(i, dummy.matrix);
        
        // Wick
        dummy.position.set(posX, wickY, posZ);
        dummy.scale.set(4, wickHeight, 4);
        dummy.updateMatrix();
        wickRef.current.setMatrixAt(i, dummy.matrix);
        
        // Color (Brighter green towards the back)
        if (isBullish && z > 40) {
            tempColor.set('#00ff44');
        } else {
            tempColor.set(isBullish ? '#00cc55' : '#ff0033');
        }
        
        bodyRef.current.setColorAt(i, tempColor);
        wickRef.current.setColorAt(i, tempColor);
        
        i++;
      }
    }
    
    bodyRef.current.instanceMatrix.needsUpdate = true;
    if (bodyRef.current.instanceColor) bodyRef.current.instanceColor.needsUpdate = true;
    wickRef.current.instanceMatrix.needsUpdate = true;
    if (wickRef.current.instanceColor) wickRef.current.instanceColor.needsUpdate = true;
  }, []);

  return (
    <group position={[0, -200, 0]}>
      <instancedMesh ref={bodyRef} args={[null, null, count]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshBasicMaterial toneMapped={false} />
      </instancedMesh>
      
      <instancedMesh ref={wickRef} args={[null, null, count]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshBasicMaterial toneMapped={false} />
      </instancedMesh>
    </group>
  );
};

