// --- MAIN COMPONENT ---
const ContangoQuant = ({ position, rotation, visible }) => {
  const scroll = useScroll();
  const lockRef = useRef({ triggered: false, timer: 0, locked: false });

  useFrame((state, delta) => {
    if (!visible) return;
    const p = scroll.offset;
    const s = lockRef.current;
    
    if (!s.triggered && p >= 0.92) {
      s.triggered = true;
      s.locked = true;
      if (scroll.el) {
        scroll.el.style.overflow = 'hidden';
        scroll.el.scrollTop = 0.93 * (scroll.el.scrollHeight - scroll.el.clientHeight);
      }
    }
    
    if (s.locked) {
      s.timer += delta;
      if (s.timer > 2.0) {
        s.locked = false;
        if (scroll.el) scroll.el.style.overflow = 'auto';
      } else {
        if (scroll.el) scroll.el.scrollTop = 0.93 * (scroll.el.scrollHeight - scroll.el.clientHeight);
      }
    }
  });

  return (
    <group visible={visible} position={position} rotation={rotation}>
      <ambientLight intensity={0.2} color="#ffffff" />
      <directionalLight position={[0, 1000, 0]} intensity={1.0} color="#ffffff" />
      
      {/* City of Charts Skyline */}
      <CityOfCharts visible={visible} />
      <FloatingDataOverlays />
      <DarkPool />

      <Float speed={1.5} rotationIntensity={0.02} floatIntensity={0.2}>
        <Image url="/contango_quant_logo.png" position={[0, 350, -800]} scale={[300, 300]} transparent opacity={0.9} />
        <Text position={[0, 170, -800]} fontSize={100} font="/fonts/Roboto.woff" fallbackFonts={[]} color="#ffffff" letterSpacing={0.1}>
          CONTANGO QUANT
        </Text>
        <Text position={[0, 80, -800]} fontSize={35} font="/fonts/Roboto.woff" fallbackFonts={[]} color="#ffaa00" letterSpacing={0.2}>
          THE PHYSICS OF FINANCE
        </Text>
      </Float>

      {/* Atmospheric Fog removed to prevent R3F crashes (cannot attach fog to group) */}

      {visible && <AvatarSystem position={[0, -50, -400]} scale={2.0} greeting="Welcome to the City of Charts. Market structures mapped." />}
    </group>
  );
};

export default ContangoQuant;
